import XCTest
@testable import Lookahead

/// The sample is generated by the laptop's own tests (tests/server/__fixtures__/phone-sample.json),
/// so decoding it proves the Swift models match the server contract.
final class ModelsTests: XCTestCase {
    private func sample() throws -> PhoneSummary {
        let url = try XCTUnwrap(Bundle(for: Self.self).url(forResource: "phone-sample", withExtension: "json")
            ?? Bundle.main.url(forResource: "phone-sample", withExtension: "json"))
        return try PhoneSummary.decode(Data(contentsOf: url))
    }

    func testSampleDecodes() throws {
        let s = try sample()
        XCTAssertEqual(s.stage.scenarioId, "scn-riser-leak")
        XCTAssertEqual(s.forecast.racksTotal, 48)
        XCTAssertFalse(s.problems.isEmpty)
        XCTAssertTrue(s.clocks.allSatisfy { $0.inMin > 0 })
    }

    func testNullsAndUnknownSeverity() throws {
        let json = """
        {"now":1,"stage":{"scenarioId":"x","headline":"h","kind":"random","basis":"b","t":0,"horizon":60,"wallClock":"02:10","playing":false,"speed":1,"autoPause":true,"lookaheadMin":0,"last":""},
         "forecast":{"firstRackLossIn":null,"firstRackAssetId":null,"racksTotal":48,"racksLost":0,"racksAtRisk":0,"assetsLost":0,"servicesAtRisk":0,"savedByFixes":0},
         "clocks":[{"assetId":"A","name":"A","inMin":5,"p10In":4,"p90In":6,"severity":"weird"}],"problems":[],"fixes":[],
         "rig":{"mode":"disconnected","inletC":null,"outletC":null,"referenceC":null,"deltaC":null,"floorWet":null,"ageS":null},
         "director":{"configured":false,"model":"m"}}
        """
        let s = try PhoneSummary.decode(Data(json.utf8))
        XCTAssertNil(s.forecast.firstRackLossIn)
        XCTAssertEqual(s.clocks.first?.severity, .normal)
        XCTAssertNil(s.rig.inletC)
    }

    func testAddressNormalizing() {
        XCTAssertEqual(BridgeClient.baseURL(from: "192.168.1.20")?.absoluteString, "http://192.168.1.20:5173")
        XCTAssertEqual(BridgeClient.baseURL(from: " http://10.0.0.5:5173/ ")?.absoluteString, "http://10.0.0.5:5173")
        XCTAssertNil(BridgeClient.baseURL(from: ""))
    }

    func testFormatting() {
        XCTAssertEqual(Format.minutes(0.4), "<1")
        XCTAssertEqual(Format.minutes(7.4), "7")
        XCTAssertNil(Format.range(15, 15))
        XCTAssertEqual(Format.range(12, 18), "12–18 min")
        XCTAssertEqual(Format.inletSeverity(26.9), .normal)
        XCTAssertEqual(Format.inletSeverity(28), .warning)
        XCTAssertEqual(Format.inletSeverity(33), .critical)
        XCTAssertEqual(Severity.forMinutesLeft(10), .critical)
        XCTAssertEqual(Severity.forMinutesLeft(30), .warning)
        XCTAssertEqual(Severity.forMinutesLeft(31), .normal)
    }

    func testStageCommandEncodingOmitsNils() throws {
        let data = try JSONEncoder().encode(StageCommand.lookahead(20))
        let obj = try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? [String: Any])
        XCTAssertEqual(obj["type"] as? String, "lookahead")
        XCTAssertEqual(obj["min"] as? Double, 20)
        XCTAssertNil(obj["dt"])
    }
}
